// Newtons Egg:  https://www.2dcurves.com/cubic/cubicn.html
float Egg1 (in vec2 p, in float a, in float b) 
{
  // 4*x^2 - (y^2-2) * (y-0.5);   // Newtons Egg
  return 4.0*p.x*p.x - (p.y*p.y-a) * (p.y-b) ;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
  vec2 p = (2.0*fragCoord-iResolution.xy)/iResolution.y;
  float px = 2.0 / iResolution.y;
  p.y += 2.2 * iMouse.y / iResolution.y;

  float ra = 0.5 + 0.3*cos(iTime);
  //~~~~~~~~~~~~~~~~~~~~~~~~~~
  float d = Egg1 (p, ra, 2.0);
  //~~~~~~~~~~~~~~~~~~~~~~~~~~

  // coloring
  vec3 col = (d > 0.0) ? vec3(0.9, 0.6, 0.3) : vec3(0.6, 0.8, 1.0);
  col *= 1.0 - exp(-7.0*abs(d));
  col *= 0.8 + 0.2*cos(90.0*abs(d));
  col = mix (col, vec3(1.0), 1.0-smoothstep(0.0,px,abs(d)-0.03));
  fragColor = vec4(col, 1.0);
}
